arguments.file_text:
namespace sv_751c7846608d4d709bafde9e91c7cadb.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_751c7846608d4d709bafde9e91c7cadb.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < Steps.Length; i++)
        {
            var index = i;
            var stepClass = GetStepClass(index);
            <li class="step-item @stepClass">
                @if (index < CurrentStep)
                {
                    <button class="step-button" @onclick="() => OnStepClicked.InvokeAsync(index)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@Steps[index]</span>
                    </button>
                }
                else
                {
                    <span class="step-button" aria-current="@(index == CurrentStep ? "step" : null)">
                        <span class="step-icon">@(index + 1)</span>
                        <span class="step-label">@Steps[index]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] Steps = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string GetStepClass(int index)
    {
        if (index < CurrentStep) return "completed";
        if (index == CurrentStep) return "active";
        return "future";
    }
}

.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    gap: 0.5rem;
}

.step-item {
    flex: 1;
    text-align: center;
    padding: 0.75rem 0.5rem;
    border-bottom: 3px solid #e0e0e0;
    transition: border-color 0.2s;
}

.step-item.completed {
    border-bottom-color: #28a745;
}

.step-item.active {
    border-bottom-color: #0d6efd;
}

.step-item.future {
    opacity: 0.5;
}

.step-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    background: none;
    border: none;
    cursor: default;
    font: inherit;
    color: inherit;
    padding: 0;
    width: 100%;
}

.step-item.completed .step-button {
    cursor: pointer;
}

.step-item.completed .step-button:hover {
    color: #28a745;
}

.step-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    background: #e0e0e0;
    font-weight: bold;
    font-size: 0.85rem;
}

.step-item.completed .step-icon {
    background: #28a745;
    color: white;
}

.step-item.active .step-icon {
    background: #0d6efd;
    color: white;
}

.step-label {
    font-size: 0.8rem;
    font-weight: 500;
}

