toolArgs.file_text:
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    gap: 0.5rem;
}

.step-item {
    flex: 1;
    text-align: center;
    padding: 0.75rem 0.5rem;
    border-bottom: 3px solid #e0e0e0;
    transition: border-color 0.2s;
}

.step-item.completed {
    border-bottom-color: #28a745;
}

.step-item.active {
    border-bottom-color: #0d6efd;
}

.step-item.future {
    opacity: 0.5;
}

.step-button {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.25rem;
    background: none;
    border: none;
    cursor: default;
    font: inherit;
    color: inherit;
    padding: 0;
    width: 100%;
}

.step-item.completed .step-button {
    cursor: pointer;
}

.step-item.completed .step-button:hover {
    color: #28a745;
}

.step-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    background: #e0e0e0;
    font-weight: bold;
    font-size: 0.85rem;
}

.step-item.completed .step-icon {
    background: #28a745;
    color: white;
}

.step-item.active .step-icon {
    background: #0d6efd;
    color: white;
}

.step-label {
    font-size: 0.8rem;
    font-weight: 500;
}

