@namespace sv_751c7846608d4d709bafde9e91c7cadb.Components.Pages.Apply

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (IsSubmitted)
    {
        <div class="confirmation">
            <h4>&#10003; Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
            <p>Thank you for applying. We will be in touch.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="section-header">
                <h4>Personal Information</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="section-header">
                <h4>Work History</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <small>@entry.StartDate.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="section-header">
                <h4>References</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-entry">
                    <strong>@r.Name</strong> (@r.Relationship) &mdash; @r.Email @(!string.IsNullOrWhiteSpace(r.Phone) ? $", {r.Phone}" : "")
                </div>
            }
        </section>

        <section class="review-section">
            <div class="section-header">
                <h4>Cover Letter</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditSection.InvokeAsync(3)">Edit</button>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </section>

        @if (!string.IsNullOrEmpty(submitError))
        {
            <div class="error">@submitError</div>
        }

        <div class="step-buttons">
            <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn btn-primary" @onclick="HandleSubmit" disabled="@isSubmitting">
                @(isSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = string.Empty;
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }

    private bool isSubmitting;
    private string? submitError;
    public bool IsSubmitted { get; private set; }
    public int ApplicationId { get; private set; }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var application = new JobApplication(
                new PersonalInfo(Personal.FullName, Personal.Email, Personal.Phone, Personal.Address),
                new WorkHistory(WorkEntries.Select(e => new WorkEntry(
                    e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
                References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
                CoverLetter
            );

            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

