    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       ShowRemove="@(Entries.Count > 1)"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="error">@validationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback<List<WorkEntryModel>> EntriesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? validationError;

    private async Task UpdateEntry(int index, WorkEntryModel updated)
    {
        Entries[index] = updated;
        await EntriesChanged.InvokeAsync(Entries);
    }

    private async Task RemoveEntry(int index)
    {
        Entries.RemoveAt(index);
        await EntriesChanged.InvokeAsync(Entries);
    }

    private async Task AddEntry()
    {
        Entries.Add(new WorkEntryModel());
        await EntriesChanged.InvokeAsync(Entries);
    }

    private async Task HandleNext()
    {
        validationError = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) ||
                string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                validationError = "Company, job title, and start date are required for each position.";
                return;
            }
        }
        await EntriesChanged.InvokeAsync(Entries);
        await OnNext.InvokeAsync();
    }
}

