@namespace sv_751c7846608d4d709bafde9e91c7cadb.Components.Pages.Apply

<div class="step-content">
    <h3>References</h3>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="@Entries[index]"
                       Index="index"
                       ShowRemove="@(Entries.Count > 2)"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    @if (Entries.Count < 3)
    {
        <button type="button" class="btn btn-secondary" @onclick="AddEntry">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(validationError))
    {
        <div class="error">@validationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback<List<ReferenceModel>> EntriesChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? validationError;

    private async Task UpdateEntry(int index, ReferenceModel updated)
    {
        Entries[index] = updated;
        await EntriesChanged.InvokeAsync(Entries);
    }

    private async Task RemoveEntry(int index)
    {
        Entries.RemoveAt(index);
        await EntriesChanged.InvokeAsync(Entries);
    }

    private async Task AddEntry()
    {
        if (Entries.Count < 3)
        {
            Entries.Add(new ReferenceModel());
            await EntriesChanged.InvokeAsync(Entries);
        }
    }

    private async Task HandleNext()
    {
        validationError = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Name) ||
                string.IsNullOrWhiteSpace(entry.Relationship) ||
                string.IsNullOrWhiteSpace(entry.Email))
            {
                validationError = "Name, relationship, and email are required for each reference.";
                return;
            }
        }
        await EntriesChanged.InvokeAsync(Entries);
        await OnNext.InvokeAsync();
    }
}

