{"file_text": "@page "/apply"
@namespace sv_751c7846608d4d709bafde9e91c7cadb.Components.Pages.Apply
@rendermode InteractiveServer
@using sv_751c7846608d4d709bafde9e91c7cadb.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="@personalInfo"
                              ModelChanged="m => personalInfo = m"
                              OnNext="HandlePersonalNext"
                              ApplicationService="@ApplicationService" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             EntriesChanged="e => workEntries = e"
                             OnNext="() => AdvanceTo(2)"
                             OnBack="() => GoToStep(0)" />
            break;
        case 2:
            <ReferencesStep Entries="@references"
                            EntriesChanged="e => references = e"
                            OnNext="() => AdvanceTo(3)"
                            OnBack="() => GoToStep(1)" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             CoverLetterChanged="c => coverLetter = c"
                             OnNext="() => AdvanceTo(4)"
                             OnBack="() => GoToStep(2)" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        ApplicationService="@ApplicationService"
                        OnBack="() => GoToStep(3)"
                        OnEditSection="GoToStep" />
            break;
    }
</div>

@code {
    private int currentStep;
    private int highestCompletedStep = -1;

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };
    private string coverLetter = string.Empty;

    private void HandlePersonalNext(PersonalInfoModel model)
    {
        personalInfo = model;
        AdvanceTo(1);
    }

    private void AdvanceTo(int step)
    {
        if (currentStep > highestCompletedStep)
        {
            highestCompletedStep = currentStep;
        }
        currentStep = step;
    }

    private void GoToStep(int step)
    {
        if (step <= highestCompletedStep || step == currentStep)
        {
            currentStep = step;
        }
    }
}
